// Real images generated by our own pipeline (SD 1.5, 30 steps, 768x512), bundled with the app.
// They replace stock/placeholder photos so every picture on the site is something this project actually made.
import hero from '../assets/showcase/hero.jpg';
import cabin from '../assets/showcase/cabin.jpg';
import neon from '../assets/showcase/neon.jpg';
import dragon from '../assets/showcase/dragon.jpg';
import reef from '../assets/showcase/reef.jpg';
import space from '../assets/showcase/space.jpg';
import abstract from '../assets/showcase/abstract.jpg';

export const SHOWCASE = {
  hero: { src: hero, prompt: 'a turquoise bay with a small white sailboat, rugged green cliffs, golden hour light' },
  cabin: { src: cabin, prompt: 'a cozy wooden cabin beside a calm mountain lake at golden sunset' },
  neon: { src: neon, prompt: 'a rainy neon-lit cyberpunk city street at night' },
  dragon: { src: dragon, prompt: 'a majestic dragon perched on a mountain peak at sunrise' },
  reef: { src: reef, prompt: 'a vibrant coral reef with tropical fish and sunbeams' },
  space: { src: space, prompt: 'a glowing nebula and a ringed planet, cinematic science fiction' },
  abstract: { src: abstract, prompt: 'abstract fluid art, swirling indigo, coral and gold' },
};

const ORDER = [cabin, neon, dragon, reef, space, abstract, hero];

/** Stable pick of one showcase image for any id/seed, so a list always shows the same picture for the same item. */
export function showcaseAt(key: string | number): string {
  const s = String(key);
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return ORDER[h % ORDER.length];
}
